use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let cents = input.as_i64().unwrap();
    let n = cents / 64;
    let shares = (cents % 64) as i64;

    let mut result = serde_json::Value::new_array();
    for _ in 0..n {
        let share = shares;
        result.push(share);
    }

    result
}
